using System.Collections;using UnityEngine;
public sealed class RetroDungeonPipe:MonoBehaviour {
 public DungeonPrototype owner;public RetroDungeonSettings settings;public Vector2Int cell;public string pipeId;public Transform mouth;public bool frontal;public string[] placementIds;public Vector3 LastEmergenceOrigin{get;private set;}
 float nextAttempt;bool animating;public int SuccessfulSpawns{get;private set;}
 void Update(){if(owner==null||settings==null||animating||Time.unscaledTime<nextAttempt||owner.LaboratoryBattle)return;var delta=owner.RetroPlayerCell-cell;if(Mathf.Abs(delta.x)+Mathf.Abs(delta.y)>settings.activationSteps)return;TryActivate();}
 public bool TryActivate(){if(owner==null||animating||Time.unscaledTime<nextAttempt)return false;GameObject actor;if(!owner.TryEmitRetroPipe(settings,pipeId,out actor,placementIds!=null&&placementIds.Length>0?placementIds:null))return false;nextAttempt=Time.unscaledTime+settings.cooldownSeconds;if(actor!=null){SuccessfulSpawns++;StartCoroutine(Emerge(actor));}return true;}
 IEnumerator Emerge(GameObject actor){animating=true;var original=transform.localScale;Vector3 destination=actor.transform.position,scale=actor.transform.localScale;Vector3 origin=mouth!=null?mouth.position:transform.position+Vector3.up*(settings.pipeHeight*owner.RetroWallHeight/3);LastEmergenceOrigin=origin;actor.transform.position=origin;actor.transform.localScale=scale*.05f;for(float t=0;t<.6f;t+=Time.unscaledDeltaTime){if(actor==null||owner.RetroPipeEnteredCombat(actor,destination))break;float k=Mathf.SmoothStep(0,1,t/.6f);transform.localScale=original*(1+Mathf.Sin(k*Mathf.PI)*.1f);actor.transform.position=Vector3.Lerp(origin,destination,k)+(frontal?Vector3.zero:Vector3.up*Mathf.Sin(k*Mathf.PI)*.35f);actor.transform.localScale=scale*Mathf.Lerp(.05f,1,k);yield return null;}transform.localScale=original;if(actor!=null){if(!owner.RetroPipeEnteredCombat(actor,destination))actor.transform.position=destination;actor.transform.localScale=scale;}animating=false;}
}
